import { useNavigate } from "react-router-dom";

export default function QuizOptionsPage() {
  const navigate = useNavigate();

  const options = [
    {
      title: "Today's Tasks Quiz",
      desc: "Test what you learned today",
      icon: "📅",
      action: () => navigate("/quiz?type=today"),
    },
    {
      title: "Phase Quiz",
      desc: "Evaluate a completed phase",
      icon: "📘",
      action: () => navigate("/quiz?type=phase"),
    },
    {
      title: "Full Learning Quiz",
      desc: "Assess your entire journey",
      icon: "🌍",
      action: () => navigate("/quiz?type=full"),
    },
  ];

  return (
    <div className="min-h-screen px-6 py-12 flex flex-col items-center">

      {/* HEADER */}
      <div className="text-center max-w-xl">
        <h2 className="text-4xl font-bold text-white">
          Choose Quiz Type
        </h2>
        <p className="mt-3 text-slate-400">
          Select how you want to test your knowledge
        </p>
      </div>

      {/* OPTIONS GRID */}
      <div className="mt-12 grid gap-8 sm:grid-cols-2 lg:grid-cols-3 w-full max-w-5xl">

        {options.map((opt, index) => (
          <button
            key={index}
            onClick={opt.action}
            className="group rounded-3xl p-6 bg-gradient-to-br from-cyan-500/20 to-blue-500/20 border border-slate-700 backdrop-blur-lg shadow-lg hover:scale-105 hover:shadow-xl transition-all duration-300 text-left"
          >
            {/* ICON */}
            <div className="text-4xl mb-4">{opt.icon}</div>

            {/* TITLE */}
            <h3 className="text-xl font-semibold text-white group-hover:text-cyan-300 transition">
              {opt.title}
            </h3>

            {/* DESCRIPTION */}
            <p className="mt-2 text-sm text-slate-400">
              {opt.desc}
            </p>

            {/* CTA */}
            <div className="mt-4 text-sm font-medium text-cyan-400 group-hover:translate-x-1 transition">
              Start Quiz →
            </div>
          </button>
        ))}

      </div>

    </div>
  );
}
